@@ -0,0 +1,442 @@
+/* Distinct win / lose motion per game. Overlay only — clicks still hit the board. */
+
+.play-fit { position: relative; }
+
+.outcome {
+  position: absolute;
+  inset: 0;
+  z-index: 4;
+  pointer-events: none;
+  overflow: hidden;
+}
+
+.outcome span {
+  position: absolute;
+  left: 50%;
+  top: 50%;
+  width: 12px;
+  height: 12px;
+  margin: -6px;
+  opacity: 0;
+}
+
+/* board reactions */
+.play-fit[data-result="win"] .board,
+.play-fit[data-result="lose"] .board {
+  animation-duration: 0.7s;
+  animation-fill-mode: both;
+}
+
+.play-fit[data-game="tictactoe"][data-result="win"] .board { animation-name: board-bounce; }
+.play-fit[data-game="tictactoe"][data-result="lose"] .board { animation-name: board-shake; }
+.play-fit[data-game="connectfour"][data-result="win"] .board { animation-name: board-lift; }
+.play-fit[data-game="connectfour"][data-result="lose"] .board { animation-name: board-drop; }
+.play-fit[data-game="connectthree"][data-result="win"] .board { animation-name: board-pop; }
