-  return placeEngine({
-    id: "miserettt",
-    name: "Misère Tic-Tac-Toe",
-    description: "Classic board, flipped rules — make three-in-a-row and you lose.",
-    size: 9,
-    cols: 3,
-    depth: 5,
-    winner,
-  });
